/**
 * Hand-written editorial layer: verdicts on individual listings and editor's
 * picks on /best hubs, reviewed by a person rather than generated by the
 * ai-content cron (which writes the per-listing writeup for the whole catalog).
 *
 * Why: after the Aug and Sept 2026 spam updates, every listing and hub on the
 * site read as template + model text. These entries add judgement a reader can
 * use (what a server is best for, the gotcha, how it differs from the nearest
 * alternative) on the pages that target head searches.
 *
 * Rules for every entry:
 * - Each factual claim traces to data we hold (stars, npm downloads, our live
 *   handshake / sandbox / health-check results) or to the project's own README
 *   or repo description, which the copy attributes ("per its README").
 * - No claims we cannot check ("most popular", "best") without a number behind it.
 * - Bump `reviewedAt` when an entry is re-checked; drop an entry when the
 *   server is archived or delisted (pick ids that no longer resolve are skipped).
 */

export type ListingVerdict = {
  /** 2-4 sentences: best for, gotcha, nearest alternative. Plain text. */
  verdict: string;
  /** YYYY-MM-DD the facts in `verdict` were last checked. */
  reviewedAt: string;
};

type HubPick = {
  serverId: string;
  /** Display name, used where the listing row isn't loaded (agent Markdown). */
  name: string;
  /** Short "best for" label, e.g. "Best for MySQL". */
  label: string;
};

export type HubEditorial = {
  /** YYYY-MM-DD the picks were last reviewed. */
  reviewedAt: string;
  /** 3-5 picks in recommendation order; each needs a LISTING_VERDICTS entry. */
  picks: HubPick[];
};

