export function listingVerdict(serverId: string): ListingVerdict | undefined {
  return LISTING_VERDICTS[serverId];
}

export function hubEditorial(slug: string): HubEditorial | undefined {
  return HUB_EDITORIAL[slug];
}

/** "2026-11-11" -> "November 11, 2026" (UTC, so build and runtime agree). */
export function formatReviewedAt(date: string): string {
  return new Date(`${date}T00:00:00Z`).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    timeZone: 'UTC',
  });
}
